Tests.Query:
select 'DB vulnerable against ORACPUOCT2026_DB_19C_15 (CVE-2026-91615)' as context,0 from dual
where
    (
    (((select rtrim(replace(substr(banner,instr(banner,'19.'),10),'.','')) from v$version where lower(banner) like '%oracle%') in ('190000'))
                   )
               )
    and
    ( ( select nvl(substr(min(patch),5),'No Security Patch installed') from
    ( select min(val) as val, patch from
    (select 18 as val,decode(count(*),0,'028-No Security Patch installed','018-Oracle PSU October 2026 installed') as patch from dba_registry_sqlpatch where ((select max(cast(rtrim(replace(substr(version,instr(version,'19.3'),16),'.','')) as integer)) from dba_registry_history where (lower(version) like '%ojvmpsu%' or lower(version) like '%ojvmru%') and ((select version FROM SYS.PRODUCT_COMPONENT_VERSION where product like 'Oracle%') in ('19.0.0.0.0')))  >= 193300261020)
    )
group by patch)
where patch not like '%No Security%'
) = 'No Security Patch installed' and (SELECT count(*) FROM DBA_REGISTRY WHERE lower(comp_id) = 'javavm' and lower(status) != 'removed') > 0 
)
